(function() {
    'use strict';

    class EthnoLabAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'EthnoLab: Fieldwork Methods Lab';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    title: 'Morning Rush (7 - 9 AM)',
                    description: 'The coffee shop is packed. Customers queue impatiently, baristas call out orders rapidly, and most patrons grab their drinks and leave. A few regulars sit at the counter exchanging brief greetings with staff. Observe how traffic flow, ordering rituals, and time pressure shape behavior.',
                    ideal: { structured: 50, ethnographic: 30, artifact: 20 },
                    themePool: ['Queue behavior under pressure', 'Regular vs. new customer rituals', 'Speed-service trade-offs', 'Non-verbal communication in crowds']
                },
                {
                    title: 'Mid-Morning Remote Workers (9 - 11 AM)',
                    description: 'The rush fades. Laptops appear on every table. Customers stake out power outlets, arrange personal workspaces, and settle into long stays. Headphones go on. Observe how people claim territory, manage social boundaries, and transform a public space into a private office.',
                    ideal: { structured: 25, ethnographic: 50, artifact: 25 },
                    themePool: ['Territorial marking behavior', 'Power outlet competition', 'Headphone-as-barrier signaling', 'Workspace personalization rituals']
                },
                {
                    title: 'Lunch Hour Mixed Crowd (12 - 1 PM)',
                    description: 'The space fills with diverse groups: solo diners, meeting pairs, and small teams sharing meals. Food orders spike. Conversations overlap. Observe group dynamics, table-sharing negotiations, and how food changes the social atmosphere compared to coffee-only periods.',
                    ideal: { structured: 40, ethnographic: 40, artifact: 20 },
                    themePool: ['Group size and conversation patterns', 'Table-sharing negotiation', 'Food vs. beverage social dynamics', 'Noise management strategies']
                },
                {
                    title: 'Afternoon Quiet (2 - 4 PM)',
                    description: 'Traffic slows to a trickle. Students study with textbooks spread across tables. A few regulars read newspapers. Staff clean and restock. The soundscape shifts to background music and the hum of the espresso machine. Observe how behavior changes when space is abundant and social pressure is minimal.',
                    ideal: { structured: 20, ethnographic: 45, artifact: 35 },
                    themePool: ['Study behavior and space usage', 'Staff-customer relationship depth', 'Environmental influence on mood', 'Solitary vs. social engagement']
                },
                {
                    title: 'After-Work Social Hour (5 - 6 PM)',
                    description: 'Professionals arrive in groups. Laptops disappear, replaced by drinks and animated conversation. The atmosphere shifts from productive to social. Some customers switch from coffee to beer or wine. Observe the social transition, greeting rituals, and how the space transforms its function.',
                    ideal: { structured: 30, ethnographic: 55, artifact: 15 },
                    themePool: ['Work-to-social transition rituals', 'Beverage choice as social signal', 'Group formation patterns', 'Volume and energy escalation']
                },
                {
                    title: 'Evening Wind-Down (7 - 9 PM)',
                    description: 'The crowd thins. Couples sit close, sharing quiet conversation. A book club meets in the corner. Staff begin closing routines. Lighting dims. Observe how intimacy increases, how closing signals are communicated, and how the remaining customers respond to the shifting environment.',
                    ideal: { structured: 20, ethnographic: 40, artifact: 40 },
                    themePool: ['Intimacy and proxemics', 'Closing ritual communication', 'Lighting and behavior change', 'Community group dynamics']
                },
                {
                    title: 'Weekend Morning (Saturday 9 AM)',
                    description: 'Families with children arrive. The pace is slower. Strollers line the entrance. Parents juggle orders and kids. A local artist sketches in the corner. Newspapers and magazines appear. Observe how the weekend transforms customer demographics, pace, and spatial usage compared to weekdays.',
                    ideal: { structured: 35, ethnographic: 35, artifact: 30 },
                    themePool: ['Family navigation strategies', 'Weekend vs. weekday pace contrast', 'Child-driven spatial changes', 'Leisure consumption patterns']
                },
                {
                    title: 'Special Event: Open Mic Night',
                    description: 'The furniture is rearranged. A microphone and small stage appear. Performers warm up. The regular crowd mixes with newcomers. Social rules shift completely: strangers talk, applause punctuates the air, and the coffee shop becomes a performance venue. Observe how a special event restructures every aspect of the space and social interaction.',
                    ideal: { structured: 25, ethnographic: 50, artifact: 25 },
                    themePool: ['Space reconfiguration for events', 'Stranger interaction patterns', 'Performance and audience dynamics', 'Identity shift of a familiar space']
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    dataQuality: 0,
                    insightDepth: 0,
                    reliability: 0,
                    themesDiscovered: 0,
                    totalScore: 0,
                    allThemes: [],
                    qualityHistory: [],
                    insightHistory: [],
                    reliabilityHistory: [],
                    scoreHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    structured: 34,
                    ethnographic: 33,
                    artifact: 33,
                    focus: 'customer_flow'
                };
            }
            this._updateBriefing(state);
            this._setupSliders();
        }

        _setupSliders() {
            var self = this;
            var ids = ['structuredInput', 'ethnographicInput', 'artifactInput'];
            ids.forEach(function(id) {
                var el = document.getElementById(id);
                if (el) {
                    el.addEventListener('input', function() {
                        self._updateSliderDisplays();
                    });
                }
            });
            this._updateSliderDisplays();
        }

        _updateSliderDisplays() {
            var s = parseInt(document.getElementById('structuredInput').value) || 0;
            var e = parseInt(document.getElementById('ethnographicInput').value) || 0;
            var a = parseInt(document.getElementById('artifactInput').value) || 0;

            var sv = document.getElementById('structuredValue');
            var ev = document.getElementById('ethnographicValue');
            var av = document.getElementById('artifactValue');
            if (sv) sv.textContent = s + '%';
            if (ev) ev.textContent = e + '%';
            if (av) av.textContent = a + '%';

            var total = s + e + a;
            var totalEl = document.getElementById('allocationTotal');
            if (totalEl) {
                totalEl.textContent = total + '%';
                totalEl.style.color = (total === 100) ? '#27ae60' : '#e74c3c';
            }
        }

        _updateBriefing(state) {
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k){return k;};
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var n = idx + 1;
            // v1.1.0 FIX: field briefings (core scenario content) are now localized.
            var title = t('r' + n + '_title'); if (title === 'r' + n + '_title') title = round.title;
            var desc  = t('r' + n + '_desc');  if (desc  === 'r' + n + '_desc')  desc  = round.description;
            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = '<strong>' + title + '</strong><br><br>' + desc;
            }
        }

        validateDecisions(decisions) {
            var structuredInput = document.getElementById('structuredInput');
            var ethnographicInput = document.getElementById('ethnographicInput');
            var artifactInput = document.getElementById('artifactInput');
            var focusSelect = document.getElementById('focusSelect');

            if (structuredInput) decisions.structured = parseInt(structuredInput.value);
            if (ethnographicInput) decisions.ethnographic = parseInt(ethnographicInput.value);
            if (artifactInput) decisions.artifact = parseInt(artifactInput.value);
            if (focusSelect) decisions.focus = focusSelect.value;

            var total = decisions.structured + decisions.ethnographic + decisions.artifact;
            if (total !== 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('allocation_warning'), 'warning'
                );
                return false;
            }
            if (decisions.structured < 0 || decisions.ethnographic < 0 || decisions.artifact < 0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('negative_warning'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var ideal = round.ideal;

            var structDiff = Math.abs(d.structured - ideal.structured);
            var ethnoDiff = Math.abs(d.ethnographic - ideal.ethnographic);
            var artifDiff = Math.abs(d.artifact - ideal.artifact);
            var totalDiff = structDiff + ethnoDiff + artifDiff;

            var methodFit = Math.max(0, 100 - totalDiff);

            var dataQuality = Math.round(
                methodFit * 0.6 +
                Math.min(d.structured, 60) * 0.4 +
                (Math.random() * 10 - 5)
            );
            dataQuality = Math.max(10, Math.min(100, dataQuality));

            var insightDepth = Math.round(
                d.ethnographic * 0.5 +
                methodFit * 0.3 +
                d.artifact * 0.1 +
                (Math.random() * 10 - 5)
            );
            insightDepth = Math.max(10, Math.min(100, insightDepth));

            var reliability = Math.round(
                d.structured * 0.6 +
                methodFit * 0.25 +
                (Math.random() * 8 - 4)
            );
            reliability = Math.max(10, Math.min(100, reliability));

            var themeChance = methodFit / 100;
            var themesThisRound = 0;
            var newThemes = [];
            var availableThemes = round.themePool.filter(function(t) {
                return state.domainState.allThemes.indexOf(t) === -1;
            });
            for (var i = 0; i < availableThemes.length; i++) {
                if (Math.random() < themeChance * 0.7) {
                    newThemes.push(availableThemes[i]);
                    themesThisRound++;
                }
            }
            if (themesThisRound === 0 && availableThemes.length > 0 && methodFit > 40) {
                newThemes.push(availableThemes[0]);
                themesThisRound = 1;
            }

            state.domainState.allThemes = state.domainState.allThemes.concat(newThemes);

            var sessionScore = Math.round(
                dataQuality * 0.3 +
                insightDepth * 0.35 +
                reliability * 0.2 +
                themesThisRound * 10 * 0.15
            );
            sessionScore = Math.max(0, Math.min(100, sessionScore));

            state.domainState.dataQuality = dataQuality;
            state.domainState.insightDepth = insightDepth;
            state.domainState.reliability = reliability;
            state.domainState.themesDiscovered = state.domainState.allThemes.length;
            state.domainState.totalScore = Math.round(
                (state.domainState.totalScore * (state.currentPeriod - 1) + sessionScore) / state.currentPeriod
            );

            state.domainState.qualityHistory.push(dataQuality);
            state.domainState.insightHistory.push(insightDepth);
            state.domainState.reliabilityHistory.push(reliability);
            state.domainState.scoreHistory.push(sessionScore);

            var self = this;
            // v1.1.0 FIX: capture nextPeriod BEFORE the async. The host increments
            // state.currentPeriod synchronously after calculateResults() returns, so reading
            // it inside the timer was two rounds ahead — sessions 2-8 showed the wrong briefing.
            var nextPeriod = (state.currentPeriod || 1) + 1;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod });
            }, 500);

            return {
                period: state.currentPeriod,
                structured: d.structured,
                ethnographic: d.ethnographic,
                artifact: d.artifact,
                focus: d.focus,
                dataQuality: dataQuality,
                insightDepth: insightDepth,
                reliability: reliability,
                themesThisRound: themesThisRound,
                newThemes: newThemes,
                sessionScore: sessionScore,
                methodFit: methodFit
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('dataQualityDisplay', 'domainState.dataQuality',
                (v) => v + '/100');
            uiManager.bind('insightDepthDisplay', 'domainState.insightDepth',
                (v) => v + '/100');
            uiManager.bind('reliabilityDisplay', 'domainState.reliability',
                (v) => v + '/100');
            uiManager.bind('themesDisplay', 'domainState.themesDiscovered');
            uiManager.bind('scoreDisplay', 'domainState.totalScore',
                (v) => v + '/100');

            // v1.1.0 FIX: re-sync sim-owned briefing + slider positions after an Undo.
            var self = this;
            var undoBtn = document.getElementById('undoBtn');
            if (undoBtn && !undoBtn._elUndoBound) {
                undoBtn._elUndoBound = true;
                undoBtn.addEventListener('click', function() {
                    setTimeout(function() {
                        var st = window.mySimulation.state;
                        self._updateBriefing(st);
                        var dd = st.decisions || {};
                        var map = { structuredInput: 'structured', ethnographicInput: 'ethnographic', artifactInput: 'artifact' };
                        Object.keys(map).forEach(function(id) {
                            var el = document.getElementById(id);
                            if (el && dd[map[id]] !== undefined) el.value = dd[map[id]];
                        });
                        var fsel = document.getElementById('focusSelect');
                        if (fsel && dd.focus) fsel.value = dd.focus;
                        self._updateSliderDisplays();
                    }, 60);
                });
            }
        }

        getChartConfig() {
            return {
                qualityChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Data Quality',
                                data: [],
                                borderColor: '#3498db',
                                backgroundColor: 'rgba(52,152,219,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.3
                            },
                            {
                                label: 'Insight Depth',
                                data: [],
                                borderColor: '#9b59b6',
                                backgroundColor: 'rgba(155,89,182,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.3
                            },
                            {
                                label: 'Reliability',
                                data: [],
                                borderColor: '#e67e22',
                                backgroundColor: 'rgba(230,126,34,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.3
                            },
                            {
                                label: 'Session Score',
                                data: [],
                                borderColor: '#27ae60',
                                backgroundColor: 'rgba(39,174,96,0.15)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.3
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Research Quality Metrics' }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100 }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.qualityHistory.map(function(_, i) {
                return 'S' + (i + 1);
            });
            return {
                qualityChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.qualityHistory },
                        { data: state.domainState.insightHistory },
                        { data: state.domainState.reliabilityHistory },
                        { data: state.domainState.scoreHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var scores = history.map(function(r) { return r.results ? r.results.sessionScore || 0 : 0; });
            var totalScore = scores.reduce(function(s, v) { return s + v; }, 0);
            var avgScore = Math.round(totalScore / scores.length);
            var totalThemes = 0;
            history.forEach(function(r) {
                totalThemes += (r.results ? r.results.themesThisRound || 0 : 0);
            });

            var performance = 'Novice Ethnographer';
            if (avgScore > 45 && totalThemes >= 10) performance = 'Competent Researcher';
            if (avgScore > 60 && totalThemes >= 16) performance = 'Skilled Fieldworker';
            if (avgScore > 75 && totalThemes >= 22) performance = 'Expert Ethnographer';

            var t = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k){return k;};
            var insights = [];
            insights.push(avgScore > 60 ? t('ins_method_strong') : t('ins_method_weak'));
            insights.push(totalThemes >= 16 ? t('ins_themes_strong') : t('ins_themes_weak'));

            return {
                avgScore: avgScore,
                totalThemes: totalThemes,
                sessionsCompleted: history.length,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (results.methodFit < 40) return window.mySimulation.t('hint_poor_fit');
            if (results.themesThisRound === 0) return window.mySimulation.t('hint_no_themes');
            if (results.reliability < 30) return window.mySimulation.t('hint_low_reliability');
            if (results.insightDepth < 30) return window.mySimulation.t('hint_low_insight');
            if (results.methodFit > 80) return window.mySimulation.t('hint_great_fit');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.focus', label: 'Focus', i18nKey: 'col_focus', formatter: (v) => (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t('focus_' + v) : v },
                { key: 'decisions.structured', label: 'Struct %', i18nKey: 'col_structured', formatter: (v) => v + '%' },
                { key: 'decisions.ethnographic', label: 'Ethno %', i18nKey: 'col_ethnographic', formatter: (v) => v + '%' },
                { key: 'decisions.artifact', label: 'Artifact %', i18nKey: 'col_artifact', formatter: (v) => v + '%' },
                { key: 'results.dataQuality', label: 'Quality', i18nKey: 'col_quality' },
                { key: 'results.themesThisRound', label: 'Themes', i18nKey: 'col_themes' },
                { key: 'results.sessionScore', label: 'Score', i18nKey: 'col_score' }
            ];
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    title:              `EthnoLab: Fieldwork Methods Lab`,
                    subtitle:           `Ethnographic Research in a Coffee Shop Environment`,
                    period_label:       `Session`,
                    period_of:          `of`,
                    briefing_label:     `Field Briefing`,
                    data_quality_label: `Data Quality`,
                    insight_depth_label:`Insight Depth`,
                    reliability_label:  `Reliability`,
                    themes_label:       `Themes Found`,
                    score_label:        `Overall Score`,
                    decisions_heading:  `Method Allocation`,
                    allocation_help:    `Allocate your observation time across three methods. The total must equal 100%.`,
                    structured_label:   `Structured Observation (%)`,
                    ethnographic_label: `Ethnographic Notes (%)`,
                    artifact_label:     `Artifact Analysis (%)`,
                    total_label:        `Total:`,
                    focus_label:        `Observation Focus`,
                    focus_customer_flow:    `Customer Flow Patterns`,
                    focus_social_dynamics:  `Social Dynamics`,
                    focus_technology_use:   `Technology Interaction`,
                    focus_spatial_behavior: `Spatial Behavior`,
                    submit_btn:         `Submit Observation`,
                    undo_btn:           `Undo Last Session`,
                    history_heading:    `Field Journal`,
                    r1_title: `Morning Rush (7 - 9 AM)`,
                    r1_desc: `The coffee shop is packed. Customers queue impatiently, baristas call out orders rapidly, and most patrons grab their drinks and leave. A few regulars sit at the counter exchanging brief greetings with staff. Observe how traffic flow, ordering rituals, and time pressure shape behavior.`,
                    r2_title: `Mid-Morning Remote Workers (9 - 11 AM)`,
                    r2_desc: `The rush fades. Laptops appear on every table. Customers stake out power outlets, arrange personal workspaces, and settle into long stays. Headphones go on. Observe how people claim territory, manage social boundaries, and transform a public space into a private office.`,
                    r3_title: `Lunch Hour Mixed Crowd (12 - 1 PM)`,
                    r3_desc: `The space fills with diverse groups: solo diners, meeting pairs, and small teams sharing meals. Food orders spike. Conversations overlap. Observe group dynamics, table-sharing negotiations, and how food changes the social atmosphere compared to coffee-only periods.`,
                    r4_title: `Afternoon Quiet (2 - 4 PM)`,
                    r4_desc: `Traffic slows to a trickle. Students study with textbooks spread across tables. A few regulars read newspapers. Staff clean and restock. The soundscape shifts to background music and the hum of the espresso machine. Observe how behavior changes when space is abundant and social pressure is minimal.`,
